// Typed access to the embedding map generated by ml/build_map.py (map.json).
// Positions are in the unit square and come from the embeddings; each passage's
// theme is the hand-written tag from cv.json (themes are defined in themes.json).
import data from './map.json';

export type PassageKind = 'context' | 'point' | 'tools' | 'skills' | 'education' | 'fact';

export interface Passage {
  id: number;
  kind: PassageKind;
  /** Short name drawn on the map. */
  title: string;
  text: string;
  source: string;
  /** Index into `themes`; null (with x and y) for passages that are searchable but not drawn (e.g. facts). */
  theme: number | null;
  x: number | null;
  y: number | null;
  /** MiniLM WordPiece tokens in `text`. */
  tokens: number;
}

export interface Theme {
  id: number;
  key: string;
  name: string;
  summary: string;
  color: string;
  /** Passages drawn in this theme. */
  size: number;
}

export interface Label {
  term: string;
  x: number;
  y: number;
  theme: number;
  passages: number[];
}

export const themes = data.themes as Theme[];
export const passages = data.passages as Passage[];
export const labels = data.labels as Label[];
export const model = data.model;

export type MappedPassage = Passage & { x: number; y: number; theme: number };

export const mappedPassages = passages.filter((p): p is MappedPassage => p.x !== null && p.y !== null);

const themeById = new Map(themes.map((t) => [t.id, t]));

export function themeOf(id: number): Theme {
  const t = themeById.get(id);
  if (!t) throw new Error(`map.json has no theme ${id}`);
  return t;
}

/** The passages that came from one CV item, as ml/build_map.py names it ("AI Engineer, Money Means"). */
export const passagesFrom = (source: string): Passage[] => passages.filter((p) => p.source === source);


/** Decode the int8-quantised unit vectors (one row per passage, `model.dims` wide). */
export function decodeVectors(): Float32Array {
  const bytes = Uint8Array.from(atob(data.vectors), (c) => c.charCodeAt(0));
  const out = new Float32Array(bytes.length);
  const signed = new Int8Array(bytes.buffer);
  for (let i = 0; i < signed.length; i++) out[i] = signed[i] / 127;
  return out;
}


/** WordPiece splits of the name and tagline, for the intro. */
export const introTokens = data.introTokens as { name: string[]; line: string[] };


/** "Machine Learning Engineer, Acme" -> "Acme": the organisation a passage came from. */
export const orgOf = (source: string): string => source.split(', ').at(-1)!;
